1435	export async function discoverPrompts(
1436	  mcpServerName: string,
1437	  mcpClient: Client,
1438	  cliConfig: McpContext,
1439	  options?: { signal?: AbortSignal },
1440	): Promise<DiscoveredMCPPrompt[]> {
1441	  // Only request prompts if the server supports them.
1442	  if (mcpClient.getServerCapabilities()?.prompts == null) return [];
1443	
1444	  try {
1445	    const response = await mcpClient.listPrompts({}, options);
1446	    return response.prompts.map((prompt) => ({
1447	      ...prompt,
1448	      serverName: mcpServerName,
1449	      invoke: (params: Record<string, unknown>) =>
1450	        invokeMcpPrompt(
1451	          mcpServerName,
1452	          mcpClient,
1453	          prompt.name,
1454	          params,
1455	          cliConfig,
1456	        ),
1457	    }));
1458	  } catch (error) {
1459	    // It's okay if the method is not found, which is a common case.
1460	    if (error instanceof Error && error.message?.includes('Method not found')) {
1461	      return [];
1462	    }
1463	    cliConfig.emitMcpDiagnostic(
1464	      'error',
1465	      `Error discovering prompts from ${mcpServerName}: ${getErrorMessage(
1466	        error,
1467	      )}`,
1468	      error,
1469	      mcpServerName,
1470	    );
1471	    throw error;
1472	  }
1473	}
